'use strict';
const net=require('net'),assert=require('assert');
const output=[];
const server=net.createServer(socket=>{
 const handle=socket._handle;
 output.push(['server',handle.setNoDelay(true),handle.setNoDelay(false),handle.setKeepAlive(true,2,3,4),handle.setKeepAlive(false,0),handle.setKeepAlive(true,0,3,4)]);
 socket.end('ok');
}).listen(0,()=>{
 const client=net.connect(server.address().port,()=>{
  const handle=client._handle;
  output.push(['client',handle.setNoDelay(true),handle.setNoDelay(false),handle.setKeepAlive(true,2,3,4),handle.setKeepAlive(false,0),handle.setKeepAlive(true,2,0,4)]);
 });
 let data='';client.setEncoding('utf8');client.on('data',chunk=>data+=chunk);
 client.on('close',()=>{assert.strictEqual(data,'ok');server.close(()=>console.log(JSON.stringify(output.sort((a,b)=>a[0].localeCompare(b[0])))));});
});
